function renderSettings(){return `<div class="page-heading compact"><div><p class="eyebrow">MAKE ROOM FOR REAL LIFE</p><h1>Your pace. <em>Your rules.</em></h1><p class="subtitle">A ceiling on study time is permission to stop.</p><p class="small muted">LearningOS v0.5.0 · local browser storage</p></div></div><form id="settings-form" class="settings-grid"><section class="panel"><h2>Study rhythm</h2><label>Focus minutes<input name="focusMinutes" type="number" min="1" max="120" value="${state.settings.focusMinutes}" required></label><label>Break minutes<input name="breakMinutes" type="number" min="1" max="30" value="${state.settings.breakMinutes}" required></label><label>Weekday minutes<input name="dailyMinutes" type="number" min="25" max="90" value="${state.settings.dailyMinutes}" required></label><label>Saturday minutes<input name="saturdayMinutes" type="number" min="25" max="180" value="${state.settings.saturdayMinutes}" required></label><label>Weekly self-study ceiling (hours)<input name="weeklyHours" type="number" min="0" max="8" step="0.25" value="${state.settings.weeklyMinutes/60}" required></label><p class="small muted">Sunday stays free. Friday is overflow or rest. Academic work shares your available evening time with independent study. Only independent minutes count toward its weekly ceiling.</p></section><section class="panel"><h2>Protection & availability</h2><label>Study timezone<input name="timezone" value="${esc(state.settings.timezone)}" list="study-timezones" required><datalist id="study-timezones"><option value="Africa/Casablanca"><option value="UTC"><option value="Europe/Paris"><option value="Asia/Tokyo"></datalist></label><label>Exam protection<select name="examMode">${[['auto','Follow calendar'],['on','Always protect for ENSAM'],['off','Off — keep independent study']].map(([v,t])=>`<option value="${v}" ${v===state.settings.examMode?'selected':''}>${t}</option>`).join('')}</select></label><label class="checkbox"><input name="paused" type="checkbox" ${state.settings.paused?'checked':''}> Pause independent roadmap</label><p class="small muted">Exam preparation from 7 December is a suggested default. Change its dates in Calendar. Your personal readiness date stays separate from exam week.</p><button class="primary" type="submit">Save preferences</button></section>${renderPlanningSettings(state)}</form><div class="settings-grid"><section class="panel"><h2>Your data, with you.</h2><p class="muted">Sessions save immediately in this browser. Other devices have separate data. Export a backup before changing browsers or clearing storage.</p><div class="button-row"><button class="secondary" data-action="export">Export backup</button><button class="text-button" data-action="import">Restore backup</button><button class="text-button" data-action="reconcile">Reconcile attempts</button>${hasMigrationPoint?'<button class="text-button" data-action="recover-migration">Recover pre-upgrade plan</button>':''}${hasRestorePoint?'<button class="text-button" data-action="recover">Recover previous plan</button>':''}</div><p class="small muted">Export pauses your focus timer for transfer. Restore keeps a local recovery copy first. Restore replaces the plan after preview; Reconcile attempts appends compatible immutable attempts without replacing the plan.</p></section><section class="panel"><h2>Obsidian checkpoint</h2><p class="muted">Bring in a local note to review headings, or attach selected private documents to tasks. Files remain in this browser and your exported backup.</p><button class="secondary" data-action="note">Review an Obsidian note ↗</button><p class="small muted">A note is context. You confirm the next task; importing a note never completes chapters.</p></section></div>`;}
function focusTask(){return (state.timer&&state.tasks.find(t=>t.id===state.timer.taskId))||dailyChoice(state,today()).task;}
function tick(){if(!state)return;const timer=state.timer,spent=elapsed(timer),limit=(timer?.targetMinutes||state.settings.focusMinutes)*60000,left=Math.max(0,Math.ceil((limit-spent)/1000));document.title=timer?.running?String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0')+' · Focus · LearningOS':'ENSAM · Learning OS';if($('#timer-value'))$('#timer-value').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(timer&&left===0&&$('#timer-label')){$('#timer-label').textContent='FOCUS COMPLETE · REVIEW YOUR SESSION';const b=$('.timer-controls .primary');if(b){b.textContent='Review session';b.dataset.action='finish';}}if($('#break-countdown')){const b=Math.max(0,Math.ceil((state.breakUntil-Date.now())/1000));$('#break-countdown').textContent=String(Math.floor(b/60)).padStart(2,'0')+':'+String(b%60).padStart(2,'0');if(b===0)render();}if(today()!==lastDate&&!timer){lastDate=today();commit(s=>pinToday(s,lastDate));}}
