async function exportBackup(){
  try{
    if(state.timer?.running){const saved=await commit(s=>{s.timer.accumulatedMs=elapsed(s.timer);s.timer.running=false;return s;});if(!saved)return;}
    const snapshot=prepareTransfer(state),blob=new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);
    a.href=url;a.download='learning-os-backup-'+snapshot.exportedAt.replace(/[:.]/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(state.timer?'Backup exported with your focus timer paused.':'Backup exported. Keep one device as your current study space.');
  }catch(error){toast(error.message||'Could not export this backup.');}
}
function importBackup(){
  const input=document.createElement('input');input.type='file';input.accept='.json,application/json';
  input.onchange=async()=>{try{
    const file=input.files?.[0];if(!file)return;if(file.size>15000000)throw Error('Backup is too large.');
    const raw=validateBackup(JSON.parse(await file.text())),next=raw.schema===1?migrateState(raw,catalog,planning):raw;
    modal(`<p class="eyebrow">RESTORE PREVIEW</p><h2>Restore this study space?</h2><p>${next.tasks.length} tasks · ${next.events.filter(e=>e.type==='session').length} sessions${next.timer?' · paused focus session included':''}</p><p class="small muted">Backup time: ${esc(next.exportedAt||next.updatedAt||'not recorded in this older backup')}</p><p class="muted">This replaces this browser’s plan. A local recovery copy is saved first. Restore replaces the plan after preview; Reconcile attempts appends compatible immutable attempts without replacing the plan.</p><div class="dialog-actions"><button class="text-button" data-close>Cancel</button><button class="secondary" id="pre-export">Export current</button><button class="primary" id="restore">Restore</button></div>`);
    $('#pre-export').onclick=exportBackup;
    $('#restore').onclick=async()=>{
      if(state.timer){toast('Save your current session before replacing this study space.');return;}
      if(await commit(s=>prepareRestore(next,s.revision),{preservePrevious:true})){$('#modal').close();toast(next.timer?'Restored. Resume your paused focus session when ready.':'Backup restored. A local recovery copy is available in Settings.');}
    };
  }catch(error){toast(error.message||'This backup could not be read.');}};input.click();
}
async function recoverBackup(){
  try{
    const saved=await readSaved(db,'restore-point');if(!saved){toast('No previous restore point is available.');return;}
    validateBackup(saved.state);
    modal(`<p class="eyebrow">LOCAL RECOVERY COPY</p><h2>Return to before your last restore?</h2><p class="muted">${saved.state.tasks.length} tasks · ${saved.state.events.filter(e=>e.type==='session').length} sessions. This replaces your current plan. Export current work first if you want to keep it.</p><div class="dialog-actions"><button class="text-button" data-close>Cancel</button><button class="secondary" id="recover-export">Export current</button><button class="primary" id="recover-confirm">Recover previous plan</button></div>`);
    $('#recover-export').onclick=exportBackup;
    $('#recover-confirm').onclick=async()=>{
      if(state.timer){toast('Save your current session before recovering another plan.');return;}
      if(await commit(s=>prepareRestore(saved.state.schema===1?migrateState(saved.state,catalog,planning):saved.state,s.revision),{preservePrevious:true})){$('#modal').close();toast('Previous plan recovered. Your replaced plan is now the recovery copy.');}
    };
  }catch(error){toast(error.message||'The recovery copy could not be loaded.');}
}

function importNote(){modal(`<form id="note-form"><p class="eyebrow">BRING YOUR PROGRESS WITH YOU</p><h2>Review an Obsidian note</h2><p class="muted">Paste a relevant note or choose its Markdown file. It stays in this browser. Review its headings, then choose your next task.</p><label>Markdown file<input id="note-file" type="file" accept=".md,.txt"></label><label>Note content<textarea id="note-text" rows="6" maxlength="200000" placeholder="# Matrix Transformations…"></textarea></label><div id="note-headings"></div><div class="dialog-actions"><button type="button" data-close class="text-button">Close</button><button class="primary">Inspect headings</button></div></form>`);$('#note-file').onchange=async e=>{if(!e.target.files?.[0])return;if(e.target.files[0].size>200000){toast('Choose a note under 200 KB.');return;}$('#note-text').value=await e.target.files[0].text();};$('#note-form').onsubmit=e=>{e.preventDefault();const headings=$('#note-text').value.split('\n').filter(l=>/^#{1,4} /.test(l)).slice(0,20);$('#note-headings').innerHTML=`<p class="small muted">${headings.length} headings found. Notes do not automatically mark material completed.</p><ul class="note-headings">${headings.map(h=>`<li>${esc(h.replace(/^#+ /,''))}</li>`).join('')}</ul><button type="button" id="from-note" class="secondary">Add a task from this note</button>`;$('#from-note').onclick=()=>{$('#modal').close();editTask(null,{resource:'Obsidian note',heading:headings[0]?.replace(/^#+ /,'')||'',provenance:'Manually imported note heading. Progress requires your confirmation.'});};};}
function bind(){bindCurriculumControls();document.querySelectorAll('[data-outcome]').forEach(b=>b.onclick=()=>finishDialog(b.dataset.outcome));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();window.scrollTo(0,0);});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editTask(b.dataset.edit));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});$('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>adjustDay(b.dataset.day));document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>editEvent(b.dataset.event));document.querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>{modal(`<h2>Correct this session?</h2><p class="muted">The original stays in your log. Its completion credit will be removed; a follow-up task may become ready again.</p><div class="dialog-actions"><button class="text-button" data-close>Cancel</button><button class="primary" id="confirm-undo">Correct outcome</button></div>`);$('#confirm-undo').onclick=async()=>{if(await commit(s=>{s.events.push({id:uid(),type:'void',target:b.dataset.undo,at:new Date().toISOString()});return s;}))$('#modal').close();};});
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.action;if(a==='recover-migration')recoverMigration();if(a==='catalog')catalogDialog();if(a==='reconcile')reconcileDialog();if(a==='new-window')editEvent();if(a==='timer')timerToggle();if(a==='end-break')await commit(s=>{s.breakUntil=null;return s;});if(a==='finish')finishDialog();if(a==='new')editTask();if(a==='availability')adjustDay(today());if(a==='export')exportBackup();if(a==='import')importBackup();if(a==='recover')recoverBackup();if(a==='note')importNote();if(a==='early'){const t=forecast(state,today(),14).find(p=>p.task)?.task;if(t)await commit(s=>{s.revisions.push({id:uid(),at:new Date().toISOString(),task:structuredClone(s.tasks.find(x=>x.id===t.id))});s.tasks.find(x=>x.id===t.id).notBefore=today();s.pinnedDay={day:today(),taskId:t.id,userOverride:true,reason:'You chose Begin early.'};return s;});}});
  $('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);if(state.timer){toast('Finish the active session before changing focus settings.');return;}const saved=await commit(s=>{for(const k of ['focusMinutes','breakMinutes','dailyMinutes','saturdayMinutes'])s.settings[k]=Number(f.get(k));s.settings.weeklyMinutes=Number(f.get('weeklyHours'))*60;s.settings.examMode=f.get('examMode');s.settings.timezone=f.get('timezone');s.settings.paused=f.has('paused');s.settings.pfeMode=f.has('pfeMode');s.settings.recoveryDays=String(f.get('recoveryDays')).split(',').map(x=>x.trim()).filter(Boolean);s.settings.preferredResources=f.getAll('preferredResources');s.settings.discretionaryMinutes=Array.from({length:7},(_,day)=>Number(f.get('available-'+day)));s.settings.smallResidualMinutes=Number(f.get('smallResidualMinutes'));s.settings.crossDayRescue=f.has('crossDayRescue');s.settings.campusTimetable=Array.from({length:7},(_,day)=>({day,minutes:Number(f.get('campus-'+day))})).filter(c=>c.minutes>0);const lead=Number(f.get('examPrepLeadDays')),leadChanged=lead!==s.settings.examPrepLeadDays;s.settings.examPrepLeadDays=lead;if(leadChanged)for(const w of s.calendar.filter(w=>w.kind==='exam_window'&&w.active)){const prep=s.calendar.find(x=>x.id==='prep:'+w.id)||(w.id==='exams-autumn'?s.calendar.find(x=>x.id==='exam-prep'):null);if(prep){prep.start_date=addDays(w.start_date,-Math.max(1,lead));prep.end_date_inclusive=addDays(w.start_date,-1);prep.active=lead>0;}else if(lead>0)s.calendar.push({id:'prep:'+w.id,title:'Suggested preparation · '+w.title,kind:'exam_prep',active:true,start_date:addDays(w.start_date,-lead),end_date_inclusive:addDays(w.start_date,-1),confidence:'authored_recommendation'});}for(const slot of s.calendarSlots){slot.minutes=Number(f.get('slot-'+slot.day));slot.fixed=f.has('fixed-'+slot.day);}validateBackup(s);return s;});if(saved)toast('Your preferences are saved.');});
}
